    (v_route, 'Katedrála svatých Janů v Toruni', 'Katedrála v Polsku. Památka v Polsku — kus historie přímo u trasy.', 53.00926, 18.60613, 'http://commons.wikimedia.org/wiki/Special:FilePath/Widok%20ko%C5%9Bci%C3%B3%C5%82a%20%C5%9Bw.%20Jan%C3%B3w%20w%20Toruniu%2C%20ulica%20%C5%BBeglarska.Widok%20z%20platformy%20widokowej%20-%20panoramio.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Widok%20ko%C5%9Bci%C3%B3%C5%82a%20%C5%9Bw.%20Jan%C3%B3w%20w%20Toruniu%2C%20ulica%20%C5%BBeglarska.Widok%20z%20platformy%20widokowej%20-%20panoramio.jpg"}'::text[], 0, '{"en": {"name": "Toruń Cathedral", "description": "Toruń. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Dom St. Johannes", "description": "Polnische Kathedrale. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Katedralna św. Jana Chrzciciela i św. Jana Ewangelisty w Toruniu", "description": "Świątynia katolicka. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Cathedral Basilica of St. John the Baptist and St. John the Evangelist", "description": "Kathedraal in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Juan Bautista y San Juan Evangelista", "description": "Toruń. Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Jean-Baptiste-et-Saint-Jean-l''Évangéliste", "description": "Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatých Janů v Toruni", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
