    (v_route, 'Jezioro Chełmżyńskie', 'Jezero, gmina Chełmża, okres Toruň, Polsko. Vodní plocha v Polsku — příjemný cíl vyjížďky s výhledy na hladinu.', 53.1766, 18.6432, 'http://commons.wikimedia.org/wiki/Special:FilePath/POL%20Jezioro%20Che%C5%82m%C5%BCy%C5%84skie-5.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/POL%20Jezioro%20Che%C5%82m%C5%BCy%C5%84skie-5.jpg"}'::text[], 6, '{"en": {"name": "Jezioro Chełmżyńskie", "description": "Lake, Toruń District, Poland. A body of water in Poland — a pleasant ride destination with waterside views."}, "de": {"name": "Jezioro Chełmżyńskie", "description": "Ein Gewässer in Polen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Jezioro Chełmżyńskie", "description": "Jezioro w gminie Chełmża, powiat toruński. Akwen w Polsce — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Jezioro Chełmżyńskie", "description": "Meer in Polen. Een waterpartij in Polen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Jezioro Chełmżyńskie", "description": "Una masa de agua en Polonia: un destino agradable con vistas al agua."}, "fr": {"name": "Jezioro Chełmżyńskie", "description": "Lac en Pologne. Un plan d''eau en Pologne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Jezioro Chełmżyńskie", "description": "Водойма в Польщі — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Co-Cathedral Basilica of the Most Holy Trinity, Chełmża', 'Památka v Polsku — kus historie přímo u trasy.', 53.1864, 18.614, 'http://commons.wikimedia.org/wiki/Special:FilePath/Holy%20Trinity%20church%20in%20Chelmza%20%283%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Holy%20Trinity%20church%20in%20Chelmza%20%283%29.jpg"}'::text[], 7, '{"en": {"name": "Co-Cathedral Basilica of the Most Holy Trinity, Chełmża", "description": "Church building in Chełmża, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Basilika Heilige Dreifaltigkeit (Chełmża)", "description": "Kirchengebäude in der Woiwodschaft Kujawien-Pommern, Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Konkatedralna Świętej Trójcy w Chełmży", "description": "Świątynia katolicka. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Co-Cathedral Basilica of the Most Holy Trinity, Chełmża", "description": "Kerkgebouw in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Concatedral y Basílica de la Santísima Trinidad", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique de la Sainte-Trinité", "description": "Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Co-Cathedral Basilica of the Most Holy Trinity, Chełmża", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb);
