    (v_route, 'Saint Paul''s in Lavanttal Abbey', 'Památka v Rakousku — kus historie přímo u trasy.', 46.7005, 14.8728, 'http://commons.wikimedia.org/wiki/Special:FilePath/Stift%20St%20Paul%20im%20Lavanttal%20Abbey%20church%2001.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Stift%20St%20Paul%20im%20Lavanttal%20Abbey%20church%2001.JPG"}'::text[], 5, '{"en": {"name": "Saint Paul''s in Lavanttal Abbey", "description": "Benedictine monastery in Sankt Paul im Lavanttal, Austria. A heritage sight in Austria — a piece of history right on your route."}, "de": {"name": "Stift St. Paul im Lavanttal", "description": "Benediktinerkloster in Sankt Paul im Lavanttal, Kärnten. Ein Denkmal in Österreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Sankt Paul im Lavanttal", "description": "Klasztor benedyktyński w Austrii. Zabytek w Austrii — kawałek historii tuż przy trasie."}, "nl": {"name": "Saint Paul''s in Lavanttal Abbey", "description": "Kunstmuseum in Oostenrijk. Een monument in Oostenrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Saint Paul''s in Lavanttal Abbey", "description": "Un monumento en Austria: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye Saint-Paul du Lavanttal", "description": "Musée en Autriche. Un monument en Autriche — un morceau d''histoire au bord de la route."}, "uk": {"name": "Монастир святого Павла у Лафантталі", "description": "Пам''ятка в Австрії — шматочок історії просто на маршруті."}}'::jsonb),
