    (v_route, 'Orlík', 'Zámek ve vesnici Orlík nad Vltavou. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.513, 14.17047, 'http://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%207.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%207.jpg"}'::text[], 0, '{"en": {"name": "Orlík Castle", "description": "Castle in Písek, Czech Republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Burg Orlík nad Vltavou", "description": "Burg an der Moldau in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Orlík", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Orlík Castle", "description": "Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Orlík nad Vltavou", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "château d''Orlík", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Орлик над Влтавою", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
