    (v_route, 'Gudenus cave', 'Přírodní zajímavost v Rakousku — místo na protažení nohou uprostřed přírody.', 48.44682, 15.3956, 'http://commons.wikimedia.org/wiki/Special:FilePath/Weinzierl%20am%20Walde%20-%20Gudenush%C3%B6hle%2C%20Innenbereich.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Weinzierl%20am%20Walde%20-%20Gudenush%C3%B6hle%2C%20Innenbereich.JPG"}'::text[], 7, '{"en": {"name": "Gudenus cave", "description": "Cave in Austria. A natural sight in Austria — a spot to stretch your legs amid nature."}, "de": {"name": "Gudenushöhle", "description": "Höhle in Österreich. Eine Natursehenswürdigkeit in Österreich — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Gudenus cave", "description": "Atrakcja przyrodnicza w Austrii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Gudenus cave", "description": "Een natuurbezienswaardigheid in Oostenrijk — een plek om de benen te strekken in de natuur."}, "es": {"name": "Gudenus cave", "description": "Un paraje natural en Austria: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "grotte Gudenus", "description": "Un site naturel en Autriche — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Gudenus cave", "description": "Природна пам''ятка в Австрії — місце розім''яти ноги серед природи."}}'::jsonb);
