  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'vodní nádrž Lipno', 'Vodní dílo na řece Vltavě. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 48.7, 14.06667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lipno%20nad%20Vltavou%2C%20p%C5%99ehradn%C3%AD%20hr%C3%A1z%2C%20p%C5%99ehrada.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lipno%20nad%20Vltavou%2C%20p%C5%99ehradn%C3%AD%20hr%C3%A1z%2C%20p%C5%99ehrada.JPG"}'::text[], 0, '{"en": {"name": "Lipno Reservoir", "description": "Reservoir in the Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Stausee Lipno", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Zbiornik Lipnowski", "description": "Największy sztuczny zbiornik wodny na terenie Czech. Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Lipnomeer", "description": "Stuwmeer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "vodní nádrž Lipno", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "vodní nádrž Lipno", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "vodní nádrž Lipno", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Vítkův kámen', 'Zřícenina hradu u Lipna. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 48.64505, 14.10327, 'http://commons.wikimedia.org/wiki/Special:FilePath/V%C3%ADtk%C5%AFv%20k%C3%A1men%202015-08-04.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/V%C3%ADtk%C5%AFv%20k%C3%A1men%202015-08-04.jpg"}'::text[], 1, '{"en": {"name": "Vítkův kámen", "description": "Czech castle ruin. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Vítkův hrádek", "description": "Burg in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Vítkův kámen", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Vítkův hrádek", "description": "Berg in Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Vítkův kámen", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Vítkův kámen", "description": "Château tchèque. Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Vítkův kámen", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Vyšebrodský klášter', 'Klášter ve Vyšším Brodě. Památka v Česku — kus historie přímo u trasy.', 48.62056, 14.30667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vy%C5%A1%C5%A1%C3%AD%20Brod%20%28Hohenfurth%29%20-%20Kloster.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vy%C5%A1%C5%A1%C3%AD%20Brod%20%28Hohenfurth%29%20-%20Kloster.JPG"}'::text[], 2, '{"en": {"name": "Vyšší Brod Cistercian Abbey", "description": "Monastery in Český Krumlov District of South Bohemian region. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Kloster Vyšší Brod", "description": "Kloster in Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo cystersów Vyšší Brod", "description": "Zabytkowy klasztor w Czechach. Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Klooster van Vyšší Brod", "description": "Klooster in Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Vyšebrodský klášter", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Vyšší Brod", "description": "Abbaye de la commune de Vyšší Brod (République Tchèque). Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Вишебродський монастир", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
