    (v_route, 'Xth Pavilion of the Citadel Warsaw', 'Muzeum, založené v roce 1963 v prostorách pavilonu Varšavské citadely, expozice je věnovaná památce polských politických věznů z 19.-20. století. Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 52.26667, 21.00028, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cyt40%20DSC0536.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cyt40%20DSC0536.JPG"}'::text[], 5, '{"en": {"name": "Xth Pavilion of the Citadel Warsaw", "description": "A castle in Poland — a historic stop worth the detour."}, "de": {"name": "X. Pavillon der Zitadelle Warschau", "description": "Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "X Pawilon Cytadeli Warszawskiej", "description": "Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Xth Pavilion of the Citadel Warsaw", "description": "Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Xth Pavilion of the Citadel Warsaw", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "pavillon 10 de la citadelle de Varsovie", "description": "Musée en Pologne. Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "X павільйон Варшавської цитаделі", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
