    (v_route, 'Zegrze Reservoir', 'Vodní plocha v Polsku — příjemný cíl vyjížďky s výhledy na hladinu.', 52.45028, 21.04139, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zalew%20Zegrzy%C5%84ski%2001.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zalew%20Zegrzy%C5%84ski%2001.JPG"}'::text[], 7, '{"en": {"name": "Zegrze Reservoir", "description": "Reservoir. A body of water in Poland — a pleasant ride destination with waterside views."}, "de": {"name": "Zegrze-Stausee", "description": "Stausee in Polen. Ein Gewässer in Polen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Jezioro Zegrzyńskie", "description": "Zbiornik retencyjny na rzece Narwi, utworzony w 1963 roku. Akwen w Polsce — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Zegrze Reservoir", "description": "Stuwmeer in Polen. Een waterpartij in Polen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Embalse Zegrze", "description": "Una masa de agua en Polonia: un destino agradable con vistas al agua."}, "fr": {"name": "Zegrze Reservoir", "description": "Un plan d''eau en Pologne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Зегжинське водосховище", "description": "Водойма в Польщі — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
