    (v_route, 'Katedrála Nanebevzetí Panny Marie v Płocku', 'Katedrála v Płocku. Památka v Polsku — kus historie přímo u trasy.', 52.54108, 19.68981, 'http://commons.wikimedia.org/wiki/Special:FilePath/Plock%20Cathedral%20aerial%20photograph%202019%20P01.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Plock%20Cathedral%20aerial%20photograph%202019%20P01.jpg"}'::text[], 0, '{"en": {"name": "Płock Cathedral", "description": "Cathedral. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Kathedrale von Płock", "description": "Polnische Kirche. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Katedralna Wniebowzięcia Najświętszej Maryi Panny w Płocku", "description": "Świątynia katolicka, katedra. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedrale basiliek Maria-Tenhemelopneming", "description": "Kathedraal in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral Basílica de la Asunción de la Virgen María", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Płock", "description": "Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála Nanebevzetí Panny Marie v Płocku", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
