    (v_route, 'Katedrála Nanebevzetí Panny Marie a svatého Ondřeje ve Fromborku', 'Katedrála v Polsku. Památka v Polsku — kus historie přímo u trasy.', 54.35708, 19.68167, 'http://commons.wikimedia.org/wiki/Special:FilePath/Frauenburger%20Dom%202010.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Frauenburger%20Dom%202010.jpg"}'::text[], 0, '{"en": {"name": "Archcathedral Basilica of the Assumption of the Blessed Virgin Mary and Saint Andrew in Frombork", "description": "Cathedral. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Kathedrale Mariä Himmelfahrt und St. Andreas", "description": "Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Archikatedralna Wniebowzięcia Najświętszej Maryi Panny i św. Andrzeja we Fromborku", "description": "Świątynia katolicka. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedrale basiliek van Maria-Hemelvaart en Sint-Andreas", "description": "Kathedraal in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Frombork", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de l''Assomption-et-Saint-André de Frombork", "description": "Édifice religieux en Pologne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор Успіння Богородиці та Святого Андрія", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
