    (v_route, 'Zbojnícký hrad', 'Zřícenina hradu na Slovensku. Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 48.97474, 21.3464, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rusk%C3%A1%20Nov%C3%A1%20Ves%2020%20Slovakia%2017.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rusk%C3%A1%20Nov%C3%A1%20Ves%2020%20Slovakia%2017.jpg"}'::text[], 4, '{"en": {"name": "Zbojnícký Castle", "description": "A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Zbojnícky zámok", "description": "Burg in der Slowakei. Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zbojnícký hrad", "description": "Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Zbojnícký hrad", "description": "Kasteelruïne in Ruská Nová Ves, Slowakije. Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Zbojnícký hrad", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "Zbojnícký hrad", "description": "Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Zbojnícký hrad", "description": "Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb),
