    (v_route, 'Protiturecká pevnost', 'Pevnost v Komárně, kterou tvoří Stará a Nová pevnost. Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 47.7551, 18.13536, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kom%C3%A1rno10.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kom%C3%A1rno10.JPG"}'::text[], 1, '{"en": {"name": "Fortress of Komárno", "description": "Fortress in Slovakia. A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Festung Komorn", "description": "Festung in Komorn, Slowakei. Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Protiturecká pevnost", "description": "Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Protiturecká pevnost", "description": "Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Protiturecká pevnost", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "Protiturecká pevnost", "description": "Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Protiturecká pevnost", "description": "Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb),
