    (v_route, 'Mrtvé rameno Váhu', 'Mrtvé rameno řeky Váh. Vodní plocha v Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 47.78029, 18.12409, null, '{}'::text[], 3, '{"en": {"name": "Holt-Vág", "description": "Lake in Slovakia. A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Mrtvé rameno Váhu", "description": "Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Mrtvé rameno Váhu", "description": "Akwen w Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Mrtvé rameno Váhu", "description": "Meer in Slowakije. Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Mrtvé rameno Váhu", "description": "Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Mrtvé rameno Váhu", "description": "Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Mrtvé rameno Váhu", "description": "Водойма в Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
