    (v_route, 'Listové jazero', 'Přírodní rezervace. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 47.89139, 18.05194, 'http://commons.wikimedia.org/wiki/Special:FilePath/Listove%20jazero%20-%20panoramio%20%288%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Listove%20jazero%20-%20panoramio%20%288%29.jpg"}'::text[], 5, '{"en": {"name": "Listové jazero", "description": "Protected area in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Listové jazero", "description": "Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Listové jazero", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Listové jazero", "description": "Natuurgebied in Okres Komárno, Slowakije. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Listove jazero", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Listové jazero", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Listové jazero", "description": "Природоохоронна територія в Словаччині. Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Parížske močiare', 'Národní přírodní rezervace. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 47.86528, 18.49889, 'http://commons.wikimedia.org/wiki/Special:FilePath/Par%C3%AD%C5%BEske%20mo%C4%8Diare%202.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Par%C3%AD%C5%BEske%20mo%C4%8Diare%202.JPG"}'::text[], 6, '{"en": {"name": "Parížske močiare", "description": "National nature reserve in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Parížske močiare", "description": "Sumpf in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Parížske močiare", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Parížske močiare", "description": "Natuurgebied in Okres Nové Zámky, Slowakije. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parizske mociare", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Parížske močiare", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Parížske močiare", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb);
