    (v_route, 'Bazilika svatých apoštolů Petra a Pavla v Strzegomi', 'Gotický kostel. Postaven mezi lety 1250 a 1390. Památka v Polsku — kus historie přímo u trasy.', 50.9592, 16.3494, 'http://commons.wikimedia.org/wiki/Special:FilePath/Strzegom10.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Strzegom10.JPG"}'::text[], 4, '{"en": {"name": "Saints Peter and Paul Basilica, Strzegom", "description": "Church building in Strzegom, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Basilika St. Peter und Paul", "description": "Kirche in Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Świętych Apostołów Piotra i Pawła w Strzegomiu", "description": "Zabytek nieruchomy w województwie dolnośląskim. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Bazilika svatých apoštolů Petra a Pavla v Strzegomi", "description": "Kerkgebouw in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Basílica de los Apóstoles Pedro y Pablo en Strzegom", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique collégiale des Saints Pierre et Paul à Strzegom", "description": "Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Bazilika svatých apoštolů Petra a Pavla v Strzegomi", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
