    (v_route, 'Katedrála Božského Spasitele', 'Katedrála v Ostravě. Památka v Česku — kus historie přímo u trasy.', 49.8361, 18.28895, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ostrava%2C%20katedr%C3%A1la%20Bo%C5%BEsk%C3%A9ho%20Spasitele.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ostrava%2C%20katedr%C3%A1la%20Bo%C5%BEsk%C3%A9ho%20Spasitele.JPG"}'::text[], 0, '{"en": {"name": "Cathedral of the Divine Saviour", "description": "Church in Ostrava-město District of Moravian Silesian region. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Kathedrale zum Göttlichen Erlöser", "description": "Kathedrale in Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Boskiego Zbawiciela w Ostrawie", "description": "Świątynia katolicka. Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Cathedral of the Divine Saviour", "description": "Kathedraal in Ostrava, Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral del Divino Salvador de Ostrava", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale du Divin-Sauveur d''Ostrava", "description": "Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála Božského Spasitele", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Slezskoostravský hrad', 'Český hrad. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.83056, 18.3, 'http://commons.wikimedia.org/wiki/Special:FilePath/%C5%9Al%C4%85skoostrawski%20zamek.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%C5%9Al%C4%85skoostrawski%20zamek.JPG"}'::text[], 1, '{"en": {"name": "Silesian Ostrava Castle", "description": "Castle in the Czech Republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Slezskoostravský hrad", "description": "Burg in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Śląskiej Ostrawie", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Silesian Ostrava Castle", "description": "Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Slezskoostravský hrad", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Slezskoostravský hrad", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Slezskoostravský hrad", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Areál čs. opevnění Hlučín-Darkovičky', 'Vojenské muzeum na území Hlučína. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.9252, 18.2213, 'http://commons.wikimedia.org/wiki/Special:FilePath/P%C4%9Bchotn%C3%AD%20srub%20MO-S%2019%20V%20aleji.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/P%C4%9Bchotn%C3%AD%20srub%20MO-S%2019%20V%20aleji.jpg"}'::text[], 2, '{"en": {"name": "Museum of the fortifications in Hlučín", "description": "Building in Hlučín, Czech Republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Areál čs. opevnění Hlučín-Darkovičky", "description": "Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Muzeum fortyfikacji Hulczyn", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Museum of the fortifications in Hlučín", "description": "Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Museo de las fortificaciones de Hlučín", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Areál čs. opevnění Hlučín-Darkovičky", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Areál čs. opevnění Hlučín-Darkovičky", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Žermanická přehrada', 'Přehradní hráz v Česku. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.73233, 18.44586, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sob%C4%9B%C5%A1ovice%2C%20%C5%BDermanick%C3%A1%20p%C5%99ehrada%2002.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sob%C4%9B%C5%A1ovice%2C%20%C5%BDermanick%C3%A1%20p%C5%99ehrada%2002.jpg"}'::text[], 3, '{"en": {"name": "Žermanice Dam", "description": "Dam in the Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Žermanická přehrada", "description": "Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Zalew Żermanicki", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Žermanická přehrada", "description": "Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Žermanická přehrada", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "Žermanická přehrada", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Žermanická přehrada", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
