    (v_route, 'vodní nádrž Ludkovice', 'Vodní nádrž Ludkovice byla vybudována na Ludkovickém potoku mezi obcemi Ludkovice a Pradlisko. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.1231, 17.7284, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ludkovice%2C%20p%C5%99ehrada%20%281%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ludkovice%2C%20p%C5%99ehrada%20%281%29.jpg"}'::text[], 3, '{"en": {"name": "Ludkovice Reservoir", "description": "Lake in Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Talsperre Ludkovice", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "vodní nádrž Ludkovice", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "vodní nádrž Ludkovice", "description": "Meer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "vodní nádrž Ludkovice", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "vodní nádrž Ludkovice", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "vodní nádrž Ludkovice", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Jezuitská kolej v Uherském Hradišti', 'Kulturní památka České republiky na území města Uherské Hradiště. Památka v Česku — kus historie přímo u trasy.', 49.06771, 17.45969, 'http://commons.wikimedia.org/wiki/Special:FilePath/Uhersk%C3%A9%20Hradi%C5%A1t%C4%9B%2C%20Masarykovo%20n%C3%A1m.%20%C4%8D.%2021.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Uhersk%C3%A9%20Hradi%C5%A1t%C4%9B%2C%20Masarykovo%20n%C3%A1m.%20%C4%8D.%2021.JPG"}'::text[], 4, '{"en": {"name": "Jesuit monastery (Uherské Hradiště)", "description": "A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Jesuitenkolleg (Uherské Hradiště)", "description": "Kloster in Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Jezuitská kolej v Uherském Hradišti", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Jezuitská kolej v Uherském Hradišti", "description": "Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Jezuitská kolej v Uherském Hradišti", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Jezuitská kolej v Uherském Hradišti", "description": "Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Jezuitská kolej v Uherském Hradišti", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
