    (v_route, 'Bytow', 'Hrad v Polsku. Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 54.16861, 17.49167, 'http://commons.wikimedia.org/wiki/Special:FilePath/KB%20Zamek%20Krzy%C5%BCacki%20w%20Bytowie.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/KB%20Zamek%20Krzy%C5%BCacki%20w%20Bytowie.jpg"}'::text[], 0, '{"en": {"name": "Bytów Castle", "description": "Historic site in Pomerania, Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Burg Bütow", "description": "Burg in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Bytowie", "description": "Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Bytow", "description": "Kasteel in Bytów, Polen. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Bytow", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "Burg Bütow", "description": "Château en Pologne. Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Bytow", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
