    (v_route, 'Chrám Povýšení vznešeného a životodárného kříže', 'Kostel v Bratislavě. Památka v Slovensku — kus historie přímo u trasy.', 48.1478, 17.1213, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kostol%20povysenia%20sv.%20kriza.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kostol%20povysenia%20sv.%20kriza.jpg"}'::text[], 0, '{"en": {"name": "Cathedral of the Exaltation of the Holy Cross, Bratislava", "description": "Cathedral in Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Cathedral of the Exaltation of the Venerable and Life-Creating Cross, Bratislava", "description": "Kathedrale in der Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Chrám Povýšení vznešeného a životodárného kříže", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Temple of the Exaltation of the Holy Cross", "description": "Kathedraal in Bratislava, Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de la Exaltación de la Santa Cruz", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de l''Exaltation-de-la-Sainte-Croix de Bratislava", "description": "Édifice religieux catholique à Bratislava, en Slovaquie. Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Chrám Povýšení vznešeného a životodárného kříže", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Ortodoxní synagoga', 'Synagoga v Bratislavě na Starém Městě. Památka v Slovensku — kus historie přímo u trasy.', 48.1469, 17.1123, 'http://commons.wikimedia.org/wiki/Special:FilePath/Orthodox%20Synagogue%2C%20Heydukova%20street%2C%20Bratislava.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Orthodox%20Synagogue%2C%20Heydukova%20street%2C%20Bratislava.jpg"}'::text[], 1, '{"en": {"name": "Orthodox synagogue in Bratislava", "description": "Synagogue in the Old Town of Bratislava, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Ortodoxní synagoga", "description": "Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga w Bratysławie", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Ortodoxní synagoga", "description": "Synagoge in Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Sinagoga ortodoxa de Bratislava", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue de la rue Heydukova", "description": "Synagogue dans la vieille ville de Bratislava, en Slovaquie. Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Ortodoxní synagoga", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
