    (v_route, 'Castle of the Pomeranian Dukes in Szczecinek', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 53.6935, 16.692, 'http://commons.wikimedia.org/wiki/Special:FilePath/ZAMEK%20KSI%C4%84%C5%BB%C4%84T%20POMORSKICH%20W%20SZCZECINKU%20-%20W%20CA%C5%81EJ%20OKAZA%C5%81O%C5%9ACI.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/ZAMEK%20KSI%C4%84%C5%BB%C4%84T%20POMORSKICH%20W%20SZCZECINKU%20-%20W%20CA%C5%81EJ%20OKAZA%C5%81O%C5%9ACI.jpg"}'::text[], 2, '{"en": {"name": "Castle of the Pomeranian Dukes in Szczecinek", "description": "Historic site in Szczecinek, West Pomeranian Voivodeship in Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Castle of the Pomeranian Dukes in Szczecinek", "description": "Burg in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Książąt Pomorskich w Szczecinku", "description": "Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Castle of the Pomeranian Dukes in Szczecinek", "description": "Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Castle of the Pomeranian Dukes in Szczecinek", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "Castle of the Pomeranian Dukes in Szczecinek", "description": "Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Castle of the Pomeranian Dukes in Szczecinek", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
